import java.util.Scanner

fun main() {
    val scanner = Scanner(System.`in`)
    val n = scanner.nextInt()
    val m = scanner.nextInt()

    val grid = Array(n) { BooleanArray(m) }

    var ret = false

    while (true) {
        var found = false
        outer@ for (i in 0 until n) {
            for (j in 0 until m) {
                if (!grid[i][j]) {
                    for (k in 0 until n) {
                        grid[k][j] = true
                    }
                    for (k in 0 until m) {
                        grid[i][k] = true
                    }
                    found = true
                    break@outer
                }
            }
        }

        if (!found) {
            break
        }

        ret = !ret
    }

    if (!ret) {
        println("Malvika")
    } else {
        println("Akshat")
    }
}

